import './styles.css';
import { useState, useEffect } from 'react';

// Simple pattern-based "predictions" to simulate RNN behavior
const PATTERNS: Record<string, string[]> = {
  'hel': ['l', 'p'],
  'hell': ['o', 'o'],
  'hello': [' ', '!'],
  'hello ': ['w', 't', 'f'],
  'hello w': ['o', 'o'],
  'hello wo': ['r', 'r'],
  'hello wor': ['l', 'l'],
  'hello worl': ['d', 'd'],
  'the ': ['q', 'c', 's', 'b', 'f'],
  'the q': ['u', 'u'],
  'the qu': ['i', 'i'],
  'the qui': ['c', 'e'],
  'the quic': ['k', 'k'],
  'the quick': [' ', ' '],
  'the quick ': ['b', 'f', 'r'],
  'the quick b': ['r', 'r'],
  'the quick br': ['o', 'o'],
  'the quick bro': ['w', 'w'],
  'the quick brow': ['n', 'n'],
  'the quick brown': [' ', ' '],
  'the quick brown ': ['f', 'd', 'c'],
  'the quick brown f': ['o', 'o'],
  'the quick brown fo': ['x', 'x'],
  'once': [' ', ' '],
  'once ': ['u', 'a', 'm'],
  'once u': ['p', 'p'],
  'once up': ['o', 'o'],
  'once upo': ['n', 'n'],
  'once upon': [' ', ' '],
  'once upon ': ['a', 'a'],
  'once upon a': [' ', 'n'],
  'once upon a ': ['t', 's', 'd'],
  'once upon a t': ['i', 'i'],
  'once upon a ti': ['m', 'm'],
  'once upon a tim': ['e', 'e'],
};

// Fallback character frequencies
const COMMON_NEXT: Record<string, string[]> = {
  ' ': ['t', 'a', 'i', 's', 'w', 'b', 'c', 'f'],
  'a': ['n', 't', 'r', 's', 'l', ' '],
  'e': [' ', 'r', 's', 'd', 'n', 'a'],
  'i': ['n', 's', 't', 'o', 'c', 'l'],
  'o': ['n', 'r', 'u', 'f', ' ', 't'],
  'u': ['r', 's', 't', 'n', 'l', ' '],
  't': ['h', 'o', 'i', 'e', 'a', ' '],
  'n': ['d', 'g', 't', ' ', 'e', 'c'],
  's': ['t', ' ', 'e', 's', 'i', 'o'],
  'r': ['e', 'o', 'i', 'a', ' ', 's'],
  'l': ['l', 'e', 'y', 'i', 'o', 'a'],
  'd': [' ', 'e', 'i', 's', 'o', 'a'],
  'h': ['e', 'a', 'i', 'o', ' '],
  'c': ['o', 'h', 'e', 'a', 'k'],
  'm': ['e', 'a', 'o', 'i', ' '],
  'p': ['e', 'r', 'a', 'o', 'l'],
  'f': ['o', 'r', 'i', 'e', 'a'],
  'g': ['e', 'h', 'o', 'a', ' '],
  'b': ['e', 'o', 'a', 'u', 'r'],
  'w': ['a', 'i', 'o', 'h', 'e'],
  'y': [' ', 'o', 'e', 's', 'i'],
  'k': [' ', 'e', 'i', 's'],
  'v': ['e', 'i', 'a', 'o'],
  'x': [' ', 't', 'p', 'i'],
  'j': ['u', 'o', 'a', 'e'],
  'q': ['u', 'u', 'u'],
  'z': ['e', 'a', 'o', 'i'],
};

function getPrediction(text: string): { char: string; confidence: number }[] {
  const lower = text.toLowerCase();

  // Check for known patterns
  for (let len = Math.min(lower.length, 20); len >= 3; len--) {
    const suffix = lower.slice(-len);
    if (PATTERNS[suffix]) {
      return PATTERNS[suffix].map((c, i) => ({
        char: c,
        confidence: Math.max(0.3, 0.95 - i * 0.2),
      }));
    }
  }

  // Fallback to character-based prediction
  const lastChar = lower.slice(-1);
  const options = COMMON_NEXT[lastChar] || ['e', 't', 'a', 'o', 'n'];
  return options.slice(0, 4).map((c, i) => ({
    char: c,
    confidence: Math.max(0.2, 0.7 - i * 0.15),
  }));
}

function ContextDisplay({ text }: { text: string }) {
  const chars = text.split('');
  const maxDisplay = 15;
  const displayChars = chars.slice(-maxDisplay);
  const hasMore = chars.length > maxDisplay;

  return (
    <div className="context-display">
      <div className="context-label">Context Window (what the model sees)</div>
      <div className="context-chars">
        {hasMore && <span className="ellipsis">...</span>}
        {displayChars.map((char, i) => {
          const opacity = 0.4 + (i / displayChars.length) * 0.6;
          return (
            <span 
              key={i} 
              className="context-char"
              style={{ opacity }}
            >
              {char === ' ' ? '␣' : char}
            </span>
          );
        })}
        <span className="cursor">|</span>
      </div>
      <div className="context-note">
        Older characters fade → Recent characters matter more
      </div>
    </div>
  );
}

function PredictionBar({ char, confidence, onClick }: { char: string; confidence: number; onClick: () => void }) {
  return (
    <button className="prediction-bar" onClick={onClick}>
      <div className="pred-char">{char === ' ' ? '␣' : char}</div>
      <div className="pred-bar-track">
        <div 
          className="pred-bar-fill" 
          style={{ width: `${confidence * 100}%` }}
        />
      </div>
      <div className="pred-conf">{Math.round(confidence * 100)}%</div>
    </button>
  );
}

export default function App() {
  const [input, setInput] = useState('Hello ');
  const [isGenerating, setIsGenerating] = useState(false);
  const [predictions, setPredictions] = useState<{ char: string; confidence: number }[]>([]);
  const [generatedCount, setGeneratedCount] = useState(0);

  useEffect(() => {
    if (input.length > 0) {
      setPredictions(getPrediction(input));
    } else {
      setPredictions([]);
    }
  }, [input]);

  const addChar = (char: string) => {
    setInput(prev => prev + char);
    setGeneratedCount(prev => prev + 1);
  };

  const generateNext = () => {
    if (predictions.length > 0) {
      addChar(predictions[0].char);
    }
  };

  const autoGenerate = () => {
    if (isGenerating) return;
    setIsGenerating(true);

    let count = 0;
    const interval = setInterval(() => {
      const preds = getPrediction(input + (count > 0 ? '' : ''));
      if (preds.length > 0 && count < 20) {
        setInput(prev => prev + preds[0].char);
        setGeneratedCount(prev => prev + 1);
        count++;
      } else {
        clearInterval(interval);
        setIsGenerating(false);
      }
    }, 300);
  };

  const reset = () => {
    setInput('');
    setGeneratedCount(0);
    setIsGenerating(false);
  };

  return (
    <div className="app">
      <div className="header">
        <h1>Sequence Predictor</h1>
        <p className="subtitle">
          Type text and see what the model predicts comes next.
        </p>
      </div>

      <div className="input-section">
        <label>Your Input</label>
        <input
          type="text"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setGeneratedCount(0);
          }}
          placeholder="Start typing..."
          className="text-input"
        />
        <div className="input-hint">
          Try: "Hello ", "The quick ", "Once upon a "
        </div>
      </div>

      <ContextDisplay text={input} />

      <div className="predictions-section">
        <div className="predictions-header">
          <h3>Predicted Next Characters</h3>
          <span className="click-hint">Click to add</span>
        </div>

        {predictions.length > 0 ? (
          <div className="predictions-list">
            {predictions.map((pred, i) => (
              <PredictionBar
                key={i}
                char={pred.char}
                confidence={pred.confidence}
                onClick={() => addChar(pred.char)}
              />
            ))}
          </div>
        ) : (
          <p className="no-predictions">Type something to see predictions</p>
        )}
      </div>

      <div className="controls">
        <button onClick={generateNext} disabled={predictions.length === 0 || isGenerating} className="btn primary">
          Add Top Prediction
        </button>
        <button onClick={autoGenerate} disabled={isGenerating || input.length === 0} className="btn generate">
          {isGenerating ? 'Generating...' : 'Auto-Generate 20 chars'}
        </button>
        <button onClick={reset} className="btn secondary">
          Reset
        </button>
      </div>

      <div className="stats">
        <div className="stat">
          <span className="stat-value">{input.length}</span>
          <span className="stat-label">Total Characters</span>
        </div>
        <div className="stat">
          <span className="stat-value">{generatedCount}</span>
          <span className="stat-label">Generated</span>
        </div>
      </div>

      <div className="insight-box">
        <h3>How RNNs Predict Sequences</h3>
        <p>
          At each step, the model looks at the <strong>current character</strong> plus its <strong>hidden state</strong> (memory of previous characters).
        </p>
        <p>
          Notice how predictions change based on context: "t" after "The quick " suggests "brown", while "t" after "Hello " suggests "there".
        </p>
        <p>
          <strong>The fading effect</strong> shows how older context has less influence—a limitation RNNs face with long sequences.
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #7c3aed 0%, #2563eb 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 700px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.95rem;
}

.input-section {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.input-section label {
  display: block;
  font-size: 0.8rem;
  color: #6b7280;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.text-input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1.1rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  outline: none;
  transition: border-color 0.2s;
}

.text-input:focus {
  border-color: #7c3aed;
}

.input-hint {
  font-size: 0.8rem;
  color: #9ca3af;
  margin-top: 0.5rem;
}

.context-display {
  background: #1e1b4b;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.context-label {
  font-size: 0.8rem;
  color: #a5b4fc;
  margin-bottom: 0.75rem;
}

.context-chars {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  font-family: 'Courier New', monospace;
  font-size: 1.5rem;
  min-height: 2.5rem;
}

.context-char {
  color: #c4b5fd;
  transition: opacity 0.3s;
}

.ellipsis {
  color: #6366f1;
  margin-right: 0.25rem;
}

.cursor {
  color: #a5b4fc;
  animation: blink 1s infinite;
}

@keyframes blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

.context-note {
  font-size: 0.75rem;
  color: #818cf8;
  margin-top: 0.75rem;
}

.predictions-section {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.predictions-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}

.predictions-header h3 {
  font-size: 1rem;
  color: #1f2937;
}

.click-hint {
  font-size: 0.75rem;
  color: #9ca3af;
}

.predictions-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.prediction-bar {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem;
  background: #f9fafb;
  border: 2px solid transparent;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: all 0.2s;
  width: 100%;
  text-align: left;
}

.prediction-bar:hover {
  border-color: #7c3aed;
  background: #f3e8ff;
}

.pred-char {
  width: 40px;
  height: 40px;
  background: #7c3aed;
  color: white;
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 700;
  font-family: monospace;
}

.pred-bar-track {
  flex: 1;
  height: 8px;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
}

.pred-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #7c3aed, #2563eb);
  border-radius: 4px;
  transition: width 0.3s;
}

.pred-conf {
  font-size: 0.9rem;
  font-weight: 600;
  color: #6b7280;
  min-width: 45px;
  text-align: right;
}

.no-predictions {
  color: #9ca3af;
  font-style: italic;
  text-align: center;
  padding: 1rem;
}

.controls {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.btn {
  flex: 1;
  min-width: 140px;
  padding: 0.75rem 1rem;
  border: none;
  border-radius: 0.5rem;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.btn.primary {
  background: #7c3aed;
  color: white;
}

.btn.primary:hover:not(:disabled) {
  background: #6d28d9;
}

.btn.generate {
  background: #2563eb;
  color: white;
}

.btn.generate:hover:not(:disabled) {
  background: #1d4ed8;
}

.btn.secondary {
  background: #f3f4f6;
  color: #374151;
}

.btn.secondary:hover {
  background: #e5e7eb;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.stat {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 0.75rem;
  padding: 1rem;
  text-align: center;
}

.stat-value {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
  color: white;
}

.stat-label {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.8);
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.25rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}
